    /**
     * Method to retrieve the Offer via OfferFetchOneSummary
     * @param 	summary OfferFetchOneSummary 
     * @return 	OfferFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Offer getOffer( OfferFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "OfferFetchOneSummary arg cannot be null" );
    	
    	Offer entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Offer
        	// --------------------------------------
        	CompletableFuture<Offer> futureEntity = queryGateway.query(new FindOfferQuery( new LoadOfferFilter( summary.getOfferId() ) ), ResponseTypes.instanceOf(Offer.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Offer with id " + summary.getOfferId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


