    public List<Offer> getAllOffer() 
    throws ProcessingException {
        List<Offer> list = null;

        try {
        	CompletableFuture<List<Offer>> futureList = queryGateway.query(new FindAllOfferQuery(), ResponseTypes.multipleInstancesOf(Offer.class));
        	
        	list = futureList.get();
        }
        catch( Exception exc ) {
            String errMsg = "Failed to get all Offer";
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return list;
    }

    /**
     * assign Requisition on Offer
     * @param		command AssignRequisitionToOfferCommand	
     * @exception	ProcessingException
     */     
	public void assignRequisition( AssignRequisitionToOfferCommand command ) throws ProcessingException {

		// --------------------------------------------
		// load the parent
		// --------------------------------------------
		load( command.getOfferId() );
		
		JobRequisitionService childDelegate 	= JobRequisitionService.getJobRequisitionInstance();
		OfferService parentDelegate = OfferService.getOfferInstance();			
		UUID childId = command.getAssignment().getJobRequisitionId();
		JobRequisition child = null;
		
		try {
			// --------------------------------------
	    	// best to validate the command now
	    	// --------------------------------------    
	    	validator.validate( command );    

	    	// --------------------------------------
        	// issue the command
        	// --------------------------------------    	
    		commandGateway.sendAndWait( command );

		}
        catch( Throwable exc ) {
			final String msg = "Failed to get JobRequisition using id " + childId;
			LOGGER.log( Level.WARNING,  msg );
			throw new ProcessingException( msg, exc );
        }
	}

